<?php
require_once 'config.php';require_once 'includes/auth.php';require_login();$uid=current_user_id();$s=$conn->prepare('SELECT r.id,r.status,e.title,e.category,e.event_date,e.event_time,e.venue FROM registrations r JOIN events e ON e.id=r.event_id WHERE r.user_id=? ORDER BY e.event_date ASC');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result();$page_title='My Registrations';include 'includes/header.php'; ?>
<main class="page-shell"><div class="welcome"><div><p class="eyebrow">MY EVENTS</p><h1>Registration desk</h1><p>Review every event you have registered for.</p></div></div><section class="table-card"><div class="table-wrap"><table><thead><tr><th>Event</th><th>Category</th><th>Date &amp; Time</th><th>Venue</th><th>Status</th></tr></thead><tbody><?php if(!$rows->num_rows): ?><tr><td colspan="5">No registrations yet.</td></tr><?php endif; ?><?php while($r=$rows->fetch_assoc()): ?><tr><td><strong><?= h($r['title']) ?></strong></td><td><?= h($r['category']) ?></td><td><?= h(date('d M Y',strtotime($r['event_date']))) ?> · <?= h(date('g:i A',strtotime($r['event_time']))) ?></td><td><?= h($r['venue']) ?></td><td><span class="status <?= h($r['status']) ?>"><?= h(ucfirst($r['status'])) ?></span></td></tr><?php endwhile; ?></tbody></table></div></section></main><?php include 'includes/footer.php'; ?>
